typedef struct { float x,y,z; } V;
typedef struct { float t; V p,n; int hit; } Hit;

static V vadd(V a,V b){return(V){a.x+b.x,a.y+b.y,a.z+b.z};}
static V vsub(V a,V b){return(V){a.x-b.x,a.y-b.y,a.z-b.z};}
static V vscl(V a,float s){return(V){a.x*s,a.y*s,a.z*s};}
static float vdot(V a,V b){return a.x*b.x+a.y*b.y+a.z*b.z;}
static float vlen(V a){return sqrtf(vdot(a,a));}
static V vnorm(V a){float l=vlen(a);return(V){a.x/l,a.y/l,a.z/l};}

static Hit sphere_intersect(V ro,V rd,V sc,float sr){
    Hit h={0,{0,0,0},{0,0,0},0};
    V oc=vsub(ro,sc);
    float a=vdot(rd,rd),b=2.0f*vdot(oc,rd),c=vdot(oc,oc)-sr*sr;
    float disc=b*b-4.0f*a*c;
    if(disc<0)return h;
    float sq=sqrtf(disc),t1=(-b-sq)/(2.0f*a),t2=(-b+sq)/(2.0f*a);
    float t=t1;
    if(t<0.001f){t=t2;if(t<0.001f)return h;}
    h.hit=1;h.t=t;
    h.p=vadd(ro,vscl(rd,t));
    h.n=vnorm(vsub(h.p,sc));
    return h;
}

